package web

const pageTemplate = `<!DOCTYPE html>
<html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>{{.Title}} · Garage CRM</title><link rel="icon" href="/static/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="/static/site.css"></head>
<body><div class="app"><aside class="sidebar"><a href="/" class="logo"><span class="logo-icon">◇</span>Garage CRM</a><div class="nav-label">Workspace</div><nav class="nav" aria-label="Main navigation">{{range .Nav}}<a href="{{.Href}}" {{if eq .Name $.Section}}class="active" aria-current="page"{{end}}><span class="nav-icon">{{.Icon}}</span><span class="nav-text">{{.Title}}</span></a>{{end}}</nav><div class="sidebar-bottom"><span class="tagline"><span class="dot"></span> Local &amp; private</span><p>No cloud. No account. Your data stays here.</p><div>Version 0.1.2-dev</div><form action="/quit" method="POST" class="quit-form"><input type="hidden" name="_csrf" value="{{.CSRF}}"><button type="submit" class="quit-button" aria-label="Quit Garage CRM">⏻ Quit Garage CRM</button></form></div></aside>
<main class="main"><header class="topbar"><div class="crumb">Garage <strong>/ {{.Title}}</strong></div>
<form action="{{if eq .Mode "list"}}/list{{else if eq .Mode "board"}}/board{{else if eq .Mode "reports"}}/reports{{else}}/{{end}}" method="GET" aria-label="Filter by brand">{{if eq .Mode "list"}}<input type="hidden" name="type" value="{{.Entity.Name}}">{{end}}<select class="brand-filter" name="brand" aria-label="Select brand">{{range .BrandOptions}}<option value="{{.ID}}" {{if eq .ID $.Brand}}selected{{end}}>{{.Label}}</option>{{end}}</select><button class="btn small secondary" type="submit">Filter</button></form>
<form class="topsearch" action="/list" method="GET"><input type="hidden" name="type" value="{{if eq .Section "home"}}people{{else if eq .Section "reports"}}leads{{else if eq .Section "tasks"}}tasks{{else}}{{.Section}}{{end}}"><input aria-label="Search" name="q" placeholder="Search records…" value="{{.Search}}"><button type="submit">Search</button></form></header>
<div class="content">
{{if eq .Mode "dashboard"}}
<div class="eyebrow">YOUR WORKSPACE</div><div class="page-title"><div><h1>Good to have you back <span style="color:#65a996">✳</span></h1><p class="subtitle">{{.Subtitle}}</p></div><div class="flex"><a class="btn secondary" href="/record?type=people">＋ Contact</a><a class="btn" href="/record?type=leads">＋ New lead</a></div></div>
<div class="stats"><div class="stat"><span class="stat-label">Contacts</span><span class="stat-icon">♙</span><div class="stat-val">{{index .Stats "people"}}</div><div class="stat-note">Relationships in your network</div></div><div class="stat"><span class="stat-label">Active leads</span><span class="stat-icon">◎</span><div class="stat-val">{{index .Stats "leads"}}</div><div class="stat-note">{{index .Stats "newleads"}} still awaiting first contact</div></div><div class="stat"><span class="stat-label">Opportunities</span><span class="stat-icon">◇</span><div class="stat-val">{{index .Stats "opportunities"}}</div><div class="stat-note">Across your business lines</div></div><div class="stat"><span class="stat-label">Tasks due</span><span class="stat-icon">▦</span><div class="stat-val">{{index .Stats "due"}}</div><div class="stat-note">Due today or overdue</div></div><div class="stat"><span class="stat-label">Cooling</span><span class="stat-icon">◷</span><div class="stat-val">{{index .Stats "cooling"}}</div><div class="stat-note">Quiet, no next action</div></div></div>
<div class="columns"><section class="panel"><div class="panel-head"><h2>Next actions</h2><a href="/board">Open task board ↗</a></div><div class="panel-body">{{if .Tasks}}{{range .Tasks}}<div class="task-line"><div class="task-check">○</div><div style="flex:1"><a class="task-title" href="/record?type=tasks&id={{index . "id"}}">{{index . "title"}}</a><span class="muted tiny">{{if index . "due_date"}}Due {{index . "due_date"}}{{else}}No date yet{{end}}</span></div><span class="pill {{if eqs (index . "priority") "Urgent"}}bad{{else if eqs (index . "priority") "High"}}warn{{else}}neutral{{end}}">{{index . "priority"}}</span></div>{{end}}{{else}}<div class="empty"><div class="visual">✳</div><h3>Everything is up to date</h3><p>Plan the next customer conversation.</p><a href="/record?type=tasks" class="btn secondary">Add a task</a></div>{{end}}</div></section><section class="panel"><div class="panel-head"><h2>Cooling — no next action</h2><span class="muted tiny">Quiet 14+ days</span></div><div class="panel-body">{{if .Cooling}}{{range .Cooling}}<div class="task-line"><div class="task-check">◷</div><div style="flex:1"><a class="task-title" href="/record?type={{index . "entity"}}&id={{index . "id"}}">{{index . "label"}}</a><span class="muted tiny">{{if eqs (index . "entity") "opportunities"}}Opportunity{{else}}Contact{{end}}{{if index . "detail"}} · {{index . "detail"}}{{end}}</span></div><span class="pill warn">{{index . "days_since"}}d quiet</span></div>{{end}}{{else}}<div class="empty"><div class="visual">✓</div><h3>Nothing going cold</h3><p>No open deals or prospects have passed the 14-day threshold without a next task.</p></div>{{end}}</div></section><section class="panel"><div class="panel-head"><h2>Fresh leads</h2><a href="/list?type=leads">View all ↗</a></div><div class="panel-body">{{if .Leads}}{{range .Leads}}<div class="task-line"><div style="flex:1"><a class="task-title" href="/record?type=leads&id={{index . "id"}}">{{index . "title"}}</a><span class="muted tiny">Added {{formatdate (index . "created_at")}}</span></div><span class="pill neutral">{{index . "status"}}</span></div>{{end}}{{else}}<div class="empty"><div class="visual">◎</div><h3>New leads appear here</h3><p>Capture a conversation and make the next move.</p><a href="/record?type=leads" class="btn secondary">Capture a lead</a></div>{{end}}</div></section></div>
{{else if eq .Mode "list"}}
<div class="eyebrow">RECORDS · {{.Entity.Title}}</div><div class="page-title"><div><h1>{{.Title}}</h1><p class="subtitle">{{.Subtitle}}</p></div><a class="btn" href="/record?type={{.Entity.Name}}{{if .Brand}}&brand={{.Brand}}{{end}}">＋ Add {{.Entity.Title}}</a></div>
<form class="filters" action="/list" method="GET"><input type="hidden" name="type" value="{{.Entity.Name}}"><input type="hidden" name="brand" value="{{.Brand}}"><input name="q" aria-label="Filter records" placeholder="Filter by name…" value="{{.Search}}"><button class="btn secondary">Filter</button></form>
<section class="panel"><table class="list-table"><thead><tr><th>{{.Entity.Title}}</th><th>Status / context</th><th>Last updated</th><th></th></tr></thead><tbody>{{range .Rows}}<tr><td><a href="/record?type={{$.Entity.Name}}&id={{index . "id"}}">{{index . $.Entity.Label}}</a><div class="muted tiny">{{if index . "email"}}{{index . "email"}}{{else if index . "source"}}{{index . "source"}}{{else if index . "description"}}{{short (index . "description")}}{{end}}</div></td><td>{{if index . "status"}}<span class="pill neutral">{{index . "status"}}</span>{{else if index . "stage"}}<span class="pill neutral">{{index . "stage"}}</span>{{else if index . "kind"}}<span class="pill neutral">{{index . "kind"}}</span>{{else}}<span class="blank">—</span>{{end}}</td><td class="muted tiny">{{formatdate (index . "updated_at")}}</td><td><a href="/record?type={{$.Entity.Name}}&id={{index . "id"}}">Open ↗</a></td></tr>{{else}}<tr><td colspan="4"><div class="empty"><div class="visual">✦</div><h3>Nothing here yet</h3><p>Create the first record to get started.</p><a href="/record?type={{$.Entity.Name}}" class="btn secondary">Add a record</a></div></td></tr>{{end}}</tbody></table></section>
{{else if eq .Mode "form"}}
<div class="eyebrow">{{.Entity.Title}} · {{if .ID}}EDIT{{else}}CREATE{{end}}</div><div class="page-title"><div><h1>{{.Title}}</h1><p class="subtitle">Keep the useful details. The rest can wait.</p></div><a class="btn secondary" href="{{if .ID}}/record?type={{.Entity.Name}}&id={{.ID}}{{else}}/list?type={{.Entity.Name}}{{end}}">Cancel</a></div>
<div class="panel form-card"><form action="/save" method="POST"><input type="hidden" name="_csrf" value="{{.CSRF}}"><input type="hidden" name="type" value="{{.Entity.Name}}"><input type="hidden" name="id" value="{{.ID}}"><input type="hidden" name="rev" value="{{index .Record "revision"}}"><div class="field-grid">{{range .Fields}}<div class="field {{if eq .F.Kind "textarea"}}wide{{end}}"><label for="field-{{.F.Key}}">{{.F.Label}}{{if .F.Required}} *{{end}}</label>
{{if eq .F.Kind "textarea"}}<textarea id="field-{{.F.Key}}" name="{{.F.Key}}" {{if .F.Required}}required{{end}}>{{.Value}}</textarea>
{{else if eq .F.Kind "bool"}}<label><input type="checkbox" id="field-{{.F.Key}}" name="{{.F.Key}}" value="on" {{if eq .Value "1"}}checked{{end}}> Yes, suppress contact</label>
{{else if or (eq .F.Kind "brand") (eq .F.Kind "person") (eq .F.Kind "organisation") (eq .F.Kind "lead") (eq .F.Kind "opportunity") (eq .F.Kind "offer") (eq .F.Kind "campaign")}}<select id="field-{{.F.Key}}" name="{{.F.Key}}" {{if .F.Required}}required{{end}}>{{$field := .}}{{range .Options}}<option value="{{.ID}}" {{if eq .ID $field.Value}}selected{{end}}>{{.Label}}</option>{{end}}</select>
{{else if eq .F.Kind "select"}}<select id="field-{{.F.Key}}" name="{{.F.Key}}"><option value="">— Choose —</option>{{$field := .}}{{range .F.Values}}<option value="{{.}}" {{if eq . $field.Value}}selected{{end}}>{{.}}</option>{{end}}</select>
{{else}}<input id="field-{{.F.Key}}" name="{{.F.Key}}" type="{{if eq .F.Kind "number"}}number{{else if eq .F.Kind "percent"}}number{{else if eq .F.Kind "date"}}date{{else if eq .F.Kind "email"}}email{{else if eq .F.Kind "color"}}color{{else}}text{{end}}" value="{{.Value}}" {{if eq .F.Kind "percent"}}min="0" max="100"{{end}} {{if .F.Required}}required{{end}}>{{end}}</div>{{end}}</div><div class="form-actions"><button class="btn" type="submit">Save record</button><a class="btn secondary" href="/list?type={{.Entity.Name}}">Back to list</a></div></form></div>
{{else if eq .Mode "detail"}}
<div class="eyebrow">{{.Entity.Title}} · RECORD</div><div class="page-title"><div><h1>{{.Title}}</h1><p class="subtitle">{{if index .Record "updated_at"}}Updated {{formatdate (index .Record "updated_at")}}{{end}} · All history stays in one place</p></div><div class="flex"><a class="btn secondary" href="/list?type={{.Entity.Name}}">← Back</a><a class="btn" href="/record?type={{.Entity.Name}}&id={{.ID}}&edit=1">Edit record</a></div></div>
{{if .Error}}<div class="alert">{{.Error}}</div>{{else}}
<div class="detail-grid"><div><section class="panel"><div class="panel-head"><h2>Record overview</h2><span class="pill neutral">{{.Entity.Title}}</span></div><div class="panel-body"><dl style="margin:0">{{range .Entity.Fields}}<div class="keyval"><dt>{{.Label}}</dt><dd>{{if index $.Record .Key}}{{index $.Record .Key}}{{else}}<span class="muted">—</span>{{end}}</dd></div>{{end}}</dl></div></section>
{{if or (eq .Entity.Name "leads") (eq .Entity.Name "opportunities") (eq .Entity.Name "campaigns") (eq .Entity.Name "tasks")}}<section class="panel" style="margin-top:18px"><div class="panel-head"><h2>Move forward</h2></div><div class="panel-body"><form class="mini-form" action="/status" method="POST"><input type="hidden" name="_csrf" value="{{.CSRF}}"><input type="hidden" name="type" value="{{.Entity.Name}}"><input type="hidden" name="id" value="{{.ID}}"><input type="hidden" name="rev" value="{{index .Record "revision"}}"><input type="hidden" name="return" value="/record?type={{.Entity.Name}}&id={{.ID}}"><label for="status">Update stage</label><select id="status" name="status">{{if eq .Entity.Name "leads"}}{{range (index .Entity.Fields 4).Values}}<option value="{{.}}" {{if eq . (str (index $.Record "status"))}}selected{{end}}>{{.}}</option>{{end}}{{else if eq .Entity.Name "opportunities"}}{{range (index .Entity.Fields 4).Values}}<option value="{{.}}" {{if eq . (str (index $.Record "stage"))}}selected{{end}}>{{.}}</option>{{end}}{{else if eq .Entity.Name "campaigns"}}{{range (index .Entity.Fields 3).Values}}<option value="{{.}}" {{if eq . (str (index $.Record "status"))}}selected{{end}}>{{.}}</option>{{end}}{{else}}<option value="Backlog">Backlog</option><option value="To Do">To Do</option><option value="In Progress">In Progress</option><option value="Blocked">Blocked</option><option value="Done">Done</option>{{end}}</select><button type="submit" class="btn secondary">Update stage</button></form>
{{if eq .Entity.Name "leads"}}<div class="separator"></div><form action="/convert" method="POST" class="mini-form"><input type="hidden" name="_csrf" value="{{.CSRF}}"><input type="hidden" name="id" value="{{.ID}}"><input type="hidden" name="rev" value="{{index .Record "revision"}}"><input type="hidden" name="make_opportunity" value="yes"><button class="btn" type="submit">Convert to opportunity →</button></form>{{end}}
{{if eq .Entity.Name "campaigns"}}<div class="separator"></div><p class="muted tiny">Activation freezes a recipient snapshot from contacts with explicit permission. It does not send messages.</p><form action="/activate" method="POST"><input type="hidden" name="_csrf" value="{{.CSRF}}"><input type="hidden" name="id" value="{{.ID}}"><input type="hidden" name="rev" value="{{index .Record "revision"}}"><button class="btn" type="submit">Activate audience snapshot</button></form><p><a href="/recipients?id={{.ID}}">Export eligible recipient CSV ↓</a></p>{{end}}</div></section>{{end}}
{{if eq .Entity.Name "opportunities"}}<section class="panel" style="margin-top:18px"><div class="panel-head"><h2>Products / service lines</h2></div><div class="panel-body">{{range .Lines}}<div class="task-line"><span style="flex:1">{{index . "description"}}</span><strong>{{index . "amount_minor"}}</strong></div>{{else}}<p class="muted">No line items yet.</p>{{end}}<div class="separator"></div><form class="mini-form" action="/line" method="POST"><input type="hidden" name="_csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{$.ID}}"><select name="offer_id">{{range (index $.Options "offer")}}<option value="{{.ID}}">{{.Label}}</option>{{end}}</select><input name="description" placeholder="Description (optional if offer selected)"><input name="quantity_milli" type="number" value="1000" min="0" placeholder="Quantity × 1000"><input name="unit_price_minor" type="number" value="0" min="0" placeholder="Unit price (minor units)"><button class="btn secondary">Add line</button></form></div></section>{{end}}
{{if eq .Entity.Name "campaigns"}}<section class="panel" style="margin-top:18px"><div class="panel-head"><h2>Recipients · {{len .Members}}</h2></div><div class="panel-body">{{range .Members}}<div class="task-line"><div style="flex:1"><strong>{{index . "recipient_name"}}</strong><div class="muted tiny">{{index . "recipient_email"}}</div></div><span class="pill neutral">{{index . "status"}}</span></div><form class="mini-form" action="/outcome" method="POST"><input type="hidden" name="_csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{$.ID}}"><input type="hidden" name="person_id" value="{{index . "person_id"}}"><select name="status"><option>Not contacted</option><option>Contacted</option><option>Replied</option><option>Interested</option><option>Converted</option><option>Opted out</option><option>Failed</option></select><input name="note" placeholder="Manual outcome note"><button class="btn secondary small">Record outcome</button></form>{{else}}<p class="muted">Activate to snapshot your eligible contacts.</p>{{end}}<div class="separator"></div><div class="section-caption">Campaign variants</div>{{range .Variants}}<p><strong>{{index . "name"}}</strong> · {{short (index . "content")}}</p>{{else}}<p class="muted">Add an A/B variant if needed.</p>{{end}}<form class="mini-form" action="/variant" method="POST"><input type="hidden" name="_csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{$.ID}}"><input name="name" placeholder="Variant name"><textarea name="content" placeholder="Copy or message"></textarea><button class="btn secondary">Add variant</button></form></div></section>{{end}}
{{if eq .Entity.Name "people"}}<section class="panel" style="margin-top:18px"><div class="panel-head"><h2>Business relationships</h2></div><div class="panel-body">{{range .Relations}}<div class="task-line"><div style="flex:1"><strong>{{index . "brand_name"}}</strong><div class="muted tiny">{{index . "lifecycle"}} · Permission: {{index . "consent"}}</div></div>{{if eqs (index . "optout") "1"}}<span class="pill bad">Opted out</span>{{end}}</div>{{else}}<p class="muted">Associate this contact with a business line.</p>{{end}}<div class="separator"></div><form class="mini-form" action="/brand-contact" method="POST"><input type="hidden" name="_csrf" value="{{$.CSRF}}"><input type="hidden" name="person_id" value="{{$.ID}}"><select name="brand_id" required>{{range (index $.Options "brand")}}<option value="{{.ID}}">{{.Label}}</option>{{end}}</select><input name="lifecycle" placeholder="Lifecycle (e.g. Prospect)"><select name="consent"><option value="unknown">Contact permission unknown</option><option value="yes">Permission recorded as yes</option><option value="no">Permission recorded as no</option></select><label class="tiny"><input type="checkbox" name="optout"> Explicit opt-out</label><button class="btn secondary">Save relationship</button></form><div class="separator"></div><h3 style="font-size:13px">Organisations</h3>{{range .Affiliations}}<p>{{index . "organisation"}} · {{index . "role"}}</p>{{end}}<form class="mini-form" action="/affiliation" method="POST"><input type="hidden" name="_csrf" value="{{$.CSRF}}"><input type="hidden" name="person_id" value="{{$.ID}}"><select name="organisation_id" required>{{range (index $.Options "organisation")}}<option value="{{.ID}}">{{.Label}}</option>{{end}}</select><input name="role" placeholder="Role"><button class="btn secondary">Link organisation</button></form></div></section>{{end}}
{{if eq .Entity.Name "people"}}<section class="panel" style="margin-top:18px"><div class="panel-head"><h2>Contact details &amp; products</h2></div><div class="panel-body">
<div class="section-caption">Additional emails and phones</div>{{range .Emails}}<p>{{index . "email"}} <span class="muted">{{index . "kind"}}</span></p>{{end}}{{range .Phones}}<p>{{index . "phone"}} <span class="muted">{{index . "kind"}}</span></p>{{end}}
<form class="mini-form" action="/contact-detail" method="POST"><input type="hidden" name="_csrf" value="{{.CSRF}}"><input type="hidden" name="person_id" value="{{.ID}}"><select name="kind"><option value="email">Email address</option><option value="phone">Phone number</option></select><input name="value" placeholder="Additional contact detail" required><input name="label" placeholder="Work, personal, other"><button class="btn secondary">Add detail</button></form>
<div class="separator"></div><div class="section-caption">Product and service relationships</div>{{range .Interests}}<p><strong>{{index . "brand_name"}}</strong> · {{index . "offer_name"}} — {{index . "status"}}</p>{{end}}
<form class="mini-form" action="/offer-interest" method="POST"><input type="hidden" name="_csrf" value="{{.CSRF}}"><input type="hidden" name="person_id" value="{{.ID}}"><select name="offer_id" required>{{range (index .Options "offer")}}<option value="{{.ID}}">{{.Label}}</option>{{end}}</select><select name="status"><option>Interested</option><option>Prospect</option><option>Customer</option><option>Former customer</option><option>Not interested</option></select><button class="btn secondary">Save offer relationship</button></form>
</div></section><section class="panel" style="margin-top:18px"><div class="panel-head"><h2>Identity management</h2></div><div class="panel-body"><p class="muted tiny">Merging keeps historical campaign snapshots and uses the stricter opt-out state. Preview before committing.</p>
<form class="mini-form" action="/merge" method="GET"><input type="hidden" name="winner" value="{{.ID}}"><select name="loser" aria-label="Select duplicate contact">{{range (index .Options "person")}}<option value="{{.ID}}">{{.Label}}</option>{{end}}</select><button class="btn secondary">Preview duplicate merge</button></form>
<div class="separator"></div><p class="muted tiny">Permanent redaction removes personal data from live records and future exports, but not previous backups or SSD remnants. This cannot be undone.</p>
<form class="mini-form" action="/redact" method="POST"><input type="hidden" name="_csrf" value="{{.CSRF}}"><input type="hidden" name="person_id" value="{{.ID}}"><input name="confirmation" placeholder="Type DELETE to permanently redact" required><button class="btn danger">Permanently redact contact</button></form>
</div></section>{{end}}
</div><aside class="detail-aside"><section class="panel"><div class="panel-head"><h2>Interaction history</h2></div><div class="panel-body">{{range .History}}<div class="activity"><strong>{{index . "channel"}}</strong><p>{{index . "summary"}}</p><time>{{formatdate (index . "occurred_at")}}</time></div>{{else}}<p class="muted">No activity logged yet.</p>{{end}}{{if or (eq .Entity.Name "people") (eq .Entity.Name "organisations") (eq .Entity.Name "leads") (eq .Entity.Name "opportunities") (eq .Entity.Name "campaigns")}}<div class="separator"></div><form class="mini-form" action="/activity" method="POST"><input type="hidden" name="_csrf" value="{{.CSRF}}"><input type="hidden" name="type" value="{{.Entity.Name}}"><input type="hidden" name="id" value="{{.ID}}"><input type="hidden" name="brand_id" value="{{index .Record "brand_id"}}"><select name="channel"><option>Note</option><option>Call</option><option>Email (manual)</option><option>Meeting</option><option>Message (manual)</option><option>Introduction</option></select><textarea name="summary" placeholder="What happened? What did you learn?" required></textarea><input name="task_title" placeholder="Next task (optional)"><input name="due_date" type="date" aria-label="Task due date"><button class="btn">Log activity &amp; follow-up</button></form>{{end}}</div></section>
<section class="panel"><div class="panel-head"><h2>Files</h2></div><div class="panel-body">{{range .Attachments}}<p><a href="/attachment?id={{index . "id"}}">↓ {{index . "name"}}</a> <span class="muted tiny">({{index . "size"}} B)</span></p>{{else}}<p class="muted">No files attached.</p>{{end}}<form class="mini-form" action="/upload" method="POST" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="{{.CSRF}}"><input type="hidden" name="type" value="{{.Entity.Name}}"><input type="hidden" name="id" value="{{.ID}}"><input type="file" name="attachment" aria-label="Choose attachment" required><button class="btn secondary">Attach file</button></form></div></section>
<form action="/archive" method="POST"><input type="hidden" name="_csrf" value="{{.CSRF}}"><input type="hidden" name="type" value="{{.Entity.Name}}"><input type="hidden" name="id" value="{{.ID}}"><input type="hidden" name="rev" value="{{index .Record "revision"}}"><button class="btn danger" type="submit">Archive record</button></form></aside></div>{{end}}
{{else if eq .Mode "board"}}
<div class="eyebrow">YOUR WORK</div><div class="page-title"><div><h1>Task board</h1><p class="subtitle">{{.Subtitle}}</p></div><a class="btn" href="/record?type=tasks">＋ Add task</a></div><div class="board">{{range .BoardStates}}<div class="board-col"><div class="board-head">{{.}} <span class="board-count">{{len (index $.Board .)}}</span></div>{{range index $.Board .}}<article class="board-card"><a class="title" href="/record?type=tasks&id={{index . "id"}}">{{index . "title"}}</a><div class="board-meta"><span>{{if index . "due_date"}}◷ {{index . "due_date"}}{{else}}No due date{{end}}</span><span>{{index . "priority"}}</span></div><form action="/status" method="POST"><input type="hidden" name="_csrf" value="{{$.CSRF}}"><input type="hidden" name="type" value="tasks"><input type="hidden" name="id" value="{{index . "id"}}"><input type="hidden" name="rev" value="{{index . "revision"}}"><input type="hidden" name="return" value="/board?brand={{$.Brand}}"><select name="status" aria-label="Move task"><option>Backlog</option><option>To Do</option><option>In Progress</option><option>Blocked</option><option>Done</option></select><button class="btn secondary small">Move</button></form></article>{{end}}</div>{{end}}</div><p class="footnote">The board works with keyboard and without drag-and-drop or network scripts.</p>
{{else if eq .Mode "reports"}}
<div class="eyebrow">BUSINESS INTELLIGENCE</div><div class="page-title"><div><h1>Reports that tell the truth</h1><p class="subtitle">All counts are derived from recorded data. No automatic email tracking or estimated revenue received.</p></div><a class="btn secondary" href="/export">↓ Export all data</a></div>
<div class="stats"><div class="stat"><span class="stat-label">People</span><div class="stat-val">{{index .Stats "people"}}</div></div><div class="stat"><span class="stat-label">Leads</span><div class="stat-val">{{index .Stats "leads"}}</div></div><div class="stat"><span class="stat-label">Campaigns</span><div class="stat-val">{{index .Stats "campaigns"}}</div></div><div class="stat"><span class="stat-label">Tasks due</span><div class="stat-val">{{index .Stats "due"}}</div></div></div><section class="panel"><div class="panel-head"><h2>Open pipeline by stage and currency</h2></div><div class="panel-body">{{range .Stages}}<div class="report-row"><strong>{{index . "stage"}}</strong><div class="bar-track"><div class="bar" style="width:55%"></div></div><div class="muted">{{index . "total"}} · {{index . "currency"}}</div></div>{{else}}<div class="empty"><h3>No opportunities recorded</h3><p>Pipeline will populate as you qualify leads.</p></div>{{end}}<p class="footnote">Values from different currencies are not aggregated. Bars are illustrative rather than comparative measurements.</p></div></section>
{{else if eq .Mode "merge"}}<div class="eyebrow">CONTACT IDENTITY</div><div class="page-title"><div><h1>Merge contacts</h1><p class="subtitle">Keep the chosen canonical contact; archive and link the duplicate safely.</p></div></div>
<section class="panel form-card"><p><strong>Retain:</strong> {{.ID}}</p><p><strong>Merge into retained:</strong> {{.Notice}}</p><p>Linked records that may be reassociated:</p><dl>{{range $k,$v := .MergeCounts}}<div class="keyval"><dt>{{$k}}</dt><dd>{{$v}}</dd></div>{{end}}</dl><p class="footnote">Campaign snapshots retain their original recipients, while future eligibility resolves the canonical contact. Global and brand-specific opt-outs are never relaxed by a merge.</p>
<form class="mini-form" action="/merge" method="POST"><input type="hidden" name="_csrf" value="{{.CSRF}}"><input type="hidden" name="winner" value="{{.ID}}"><input type="hidden" name="loser" value="{{.Notice}}"><input name="confirm" placeholder="Type MERGE" required><button class="btn danger">Confirm merge</button></form></section>
{{else if eq .Mode "error"}}<div class="eyebrow">ACTION NOT COMPLETED</div><div class="page-title"><h1>{{.Title}}</h1></div><div class="alert">{{.Error}}</div><a href="/" class="btn secondary">Return to My Day</a>{{end}}
<div class="page-footer">GARAGE CRM · Built to stay simple · Everything runs on your computer · <a href="/export">Portable data export</a></div></div></main></div></body></html>`
